def clean(df):
    df = df.drop_duplicates().copy()
    df['Category'] = df['Category'].astype(str).str.strip()
    mapping = {c.lower(): c for c in ['Electronics', 'Accessories', 'Furniture', 'Office Supplies']}
    df['Category'] = df['Category'].map(lambda x: mapping.get(x.lower(), x))
    return df

